const appName="Lean Stories";var documentName;const FIREBASE_PROJECT_ID="leanstories-f5798";window.firebase.initializeApp({projectId:"leanstories-f5798"});const db=window.firebase.firestore(),collection=db.collection("miro");miro.onReady((async()=>{let e=await miro.board.info.get();documentName=btoa(e.id+e.createdAt)}));const getAppName=()=>appName,compareAllValues=(e,a,t=[])=>!Object.keys(e).find((o=>e[o]!==a[o]&&!t.includes(o))),allEqual=e=>e.every((a=>a===e[0])),readData=async()=>{let e=await collection.doc(documentName).get();return e.exists?e.data():(writeData({}),{})},writeData=async e=>{await collection.doc(documentName).set(e)};